package com.eidolon.sc.mobile;
import android.app.*;import android.content.*;import android.database.*;import org.json.*;import java.time.*;import java.util.*;
/** A permission-checked notification opportunity; no microphone or model before explicit acceptance. */
final class CallIncoming {
 static final int ID=9762;static final String CHANNEL="eidolon-incoming-calls-v1";
 static int offersToday(ChatStore s,ReachConfig config,long now){int count=0;try{JSONArray a=CallStore.all(s);String day=ReachPolicy.date(config,now);for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(r.optString("direction").equals("incoming")&&ReachPolicy.date(config,r.optLong("createdAt")).equals(day))count++;}}catch(Exception e){return config.integer("dailyLimit");}return count;}
 static void expire(Context c,ChatStore s,long now)throws Exception{JSONArray a=CallStore.all(s);for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(r.optString("state").equals("ringing")&&now>=r.optLong("expires")){r.put("state","missed").put("endedAt",now).put("reason","来电通知未在有效期内接听");CallStore.put(s,r);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(ID);}}}
 static void reject(Context c,String id)throws Exception{try(ChatStore s=new ChatStore(c)){JSONObject r=CallStore.get(s,id);if(r!=null&&r.optString("state").equals("ringing")){r.put("state","rejected").put("endedAt",System.currentTimeMillis()).put("reason","已拒接，不改变关系");CallStore.put(s,r);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(ID);}}}
 static JSONObject answer(Context c,ChatStore s,String id)throws Exception{expire(c,s,System.currentTimeMillis());JSONObject r=CallStore.get(s,id);if(r==null||!r.optString("state").equals("ringing"))throw new Exception("这次来电已结束");if(CallService.live()||s.hasBlockingPending(r.getString("character")))throw new Exception("还有通话或同角色待回复文字，暂不能接听");return r;}
 static void consider(Context c,ChatStore s,long now)throws Exception{synchronized(ReachPlans.LOCK){expire(c,s,now);android.content.SharedPreferences p=c.getSharedPreferences("settings",0);if(!p.getBoolean("callIncoming",false)||!p.getBoolean("reachEnabled",false)||CallService.live())return;ReachConfig config=ReachConfig.read(p);if(ReachPolicy.quiet(config,now)||offersToday(s,config,now)>0)return;
  JSONArray past=CallStore.all(s);for(int i=0;i<past.length();i++){JSONObject r=past.getJSONObject(i);if(r.optString("direction").equals("incoming")&&now-r.optLong("createdAt")<24*3600000L)return;}
  NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(!nm.areNotificationsEnabled())return;nm.createNotificationChannel(new NotificationChannel(CHANNEL,"角色主动来电",NotificationManager.IMPORTANCE_HIGH));NotificationChannel channel=nm.getNotificationChannel(CHANNEL);if(channel==null||channel.getImportance()==NotificationManager.IMPORTANCE_NONE)return;
  JSONObject personal=s.personal();Progression.upgrade(personal);JSONArray chars=WritingEngine.characters(c);for(int i=0;i<chars.length();i++){JSONObject character=chars.getJSONObject(i);String who=character.getString("id");java.util.List<ChatStore.Conversation> sessions=s.conversations(who);if(sessions.isEmpty()||s.hasBlockingPending(who))continue;String pendingTask="";try(Cursor task=s.getReadableDatabase().rawQuery("SELECT id FROM reach_tasks WHERE character=? AND status='PENDING' AND due<=? AND expires>? ORDER BY due LIMIT 1",new String[]{who,""+now,""+now})){if(task.moveToFirst())pendingTask=task.getString(0);}if(pendingTask.isEmpty()&&(ReachPlans.active(s,who)||ReachPlans.remaining(s,config,now)<=0))continue;String session=sessions.get(0).id;if(!ReachPlans.ineligible(c,s,config,personal,who,session,now).isEmpty()||!ReachPlanRules.suitable(ScheduleRuntime.state(c,s,personal,who,now))||now-ReachPlans.contactAt(s,session)<config.integer("recentMinutes")*60000L||!ReachPlans.deliveryGap(s,config,now))continue;
   String id=UUID.randomUUID().toString();Intent open=new Intent(c,WebActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("incomingCallId",id);PendingIntent accept=PendingIntent.getActivity(c,9762,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent reject=PendingIntent.getBroadcast(c,9763,new Intent(c,CallIncomingReceiver.class).putExtra("callId",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
   Notification.Builder n=new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.sym_call_incoming).setContentTitle(character.optString("name")+" · 应用内来电").setContentText("接听后才启用麦克风与模型，拒接不改变关系").setCategory(Notification.CATEGORY_CALL).setContentIntent(accept).setDeleteIntent(reject).setTimeoutAfter(60000).setAutoCancel(false);
   if(android.os.Build.VERSION.SDK_INT>=31)n.setStyle(Notification.CallStyle.forIncomingCall(new Person.Builder().setName(character.optString("name")).build(),reject,accept));else n.addAction(new Notification.Action.Builder(null,"拒接",reject).build()).addAction(new Notification.Action.Builder(null,"查看并接听",accept).build());
   JSONObject row=new JSONObject().put("id",id).put("character",who).put("name",character.optString("name")).put("session",session).put("state","ringing").put("direction","incoming").put("createdAt",now).put("expires",now+60000).put("connectedAt",0).put("endedAt",0).put("turnId",0).put("pending","").put("revision",0).put("heard",false).put("reason","已向系统提交来电通知，是否弹出由系统决定");
   try{nm.notify(ID,n.build());android.database.sqlite.SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{CallStore.put(s,row);if(!pendingTask.isEmpty())ReachPlanStore.skip(s,pendingTask,"用户已允许主动来电，本次联系机会已改为来电邀请（接听前不请求模型）",now);db.setTransactionSuccessful();}finally{db.endTransaction();}}catch(Exception failure){nm.cancel(ID);return;}
   android.app.job.JobInfo job=new android.app.job.JobInfo.Builder(19762,new ComponentName(c,CallMissedJob.class)).setMinimumLatency(61000).setOverrideDeadline(90000).build();((android.app.job.JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE)).schedule(job);return;
  }
 }}
 private CallIncoming(){}
}
